# Self-extracting assets bundle generated automatically
import os, zipfile, io, base64

BUNDLE_B64 = """"""

def unpack_assets(target_dir=None):
    if target_dir is None:
        target_dir = os.path.dirname(os.path.abspath(__file__))
    zip_bytes = base64.b64decode(BUNDLE_B64)
    with zipfile.ZipFile(io.BytesIO(zip_bytes)) as zf:
        zf.extractall(target_dir)
    print("[Assets Unpacker] Unpacked templates, static assets and configs successfully!")

unpack_assets()
